/**
 * The Dream
 * ----------
 * Gideon creeps to the Midianite camp with Purah and hears a dream: a barley cake rolls into the camp and flattens a tent. Stage: a vast night camp of countless fires, the men moving between tents, a dreamer and his companion; starlight and firelight, a murmuring army.
 *
 * Palette 0x100a1a → 0x0a0502 · light: night · hero: tent
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./gideon-kit.js.
 */

import { THREE, createScene, tent, wheat, army, person } from './gideon-kit.js';

const BG = 0x100a1a;
const GROUND = 0x0a0502;

export function build(group) {
    const W = createScene(group, { seed: 2753457482, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — night */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-30, 70, -150], 10, 0xfff8e8);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-40, 44, -125, 26], [30, 50, -135, 32], [85, 42, -120, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xf0f4f8, { opacity: 0.75 }), [x, y, z], { s: [s, s * 0.22, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x0a0502, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents */
    tent(W, group, -23.0, 0, -15.9, 1.13, 0xc8b088, W.r() * 6);
    tent(W, group, -24.5, 0, -21.4, 1.28, 0xc8b088, W.r() * 6);
    tent(W, group, 16.2, 0, -7.6, 1.38, 0xa8704a, W.r() * 6);
    tent(W, group, 5.8, 0, -24.8, 1.16, 0x8a6a44, W.r() * 6);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x120b1d, head: 0x140d21 });

    /* army: shields and spears in rank */
    army(W, group, -13.9, 20.4, 10, { shields: [0x0a0711, 0x090502, 0x8a7a2a, 0x3a5a8a] });

    /* hero: the tent */
    tent(W, group, 0, 0, 0, 1.4, 0x0a0502, 0.2);
    W.disc([0, 5, -10], 5, 0x150d22, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x100a1a, ry: 0.31, s: 1.16 });

    return W.finish();
}

export default { build };
